# 2server VPN - Windows installer bootstrap (ASCII-only, UTF-8 safe)
$ErrorActionPreference = 'Stop'
try { [Console]::OutputEncoding = [System.Text.Encoding]::UTF8 } catch {}
try { $OutputEncoding = [System.Text.Encoding]::UTF8 } catch {}
try { chcp 65001 > $null } catch {}
$__vpn_src = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String(''))
Invoke-Expression $__vpn_src
